<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';
import {api,attachment,dateToday,isFamilyEntry,initializeFamilyEntry,tokenStorageKey} from './api';
import ChildTasks from './ChildTasks.vue';
import {subjectCounts,filterTasks,sortTasks} from './tasks';
const me=ref<any>(null),children=ref<any[]>([]),selected=ref(''),assignments=ref<any[]>([]),imports=ref<any[]>([]),draft=ref<any>(null),devices=ref<any[]>([]);
const page=ref('today'),loginMode=ref('parent'),password=ref(''),code=ref(''),error=ref(''),notice=ref(''),busy=ref(false),date=ref(dateToday()),pending=ref(false),text=ref(''),fileInput=ref<HTMLInputElement>(),targetIds=ref<string[]>([]),name=ref(''),grade=ref(''),pairing=ref(''),pairChild=ref(''),preview=ref(''),edit=ref<any>(null);
const composerOpen=ref(false),activeSubject=ref('');
const subjects=computed(()=>subjectCounts(assignments.value).map(s=>({...s,total:assignments.value.filter(a=>a.subject===s.subject).length})));
watch(subjects,items=>{if(activeSubject.value&&!items.some(s=>s.subject===activeSubject.value))activeSubject.value='';});
const parent=computed(()=>me.value?.role==='parent'),child=computed(()=>children.value.find(c=>c.id===selected.value)),done=computed(()=>assignments.value.filter(a=>!!a.completed).length),groups=computed(()=>{const groups:Record<string,any[]>=Object.create(null);for(const s of subjects.value){const items=sortTasks(filterTasks(assignments.value,s.subject));if(!activeSubject.value||activeSubject.value===s.subject)groups[s.subject]=items;}return groups;});
const mergeSelection=ref<number[]>([]),currentImport=ref<any>(null),selectedFiles=ref<File[]>([]),selectedImages=ref<File[]>([]),fileNames=ref<string[]>([]),imageNames=ref<string[]>([]),imageInput=ref<HTMLInputElement>(),keyboardInset=ref(0);
function selectedChild(){activeSubject.value='';targetIds.value=selected.value?[selected.value]:[];rememberChild();void act(loadAssignments);}
function chooseFiles(e:Event){selectedFiles.value=Array.from((e.target as HTMLInputElement).files??[]);fileNames.value=selectedFiles.value.map(f=>f.name);}
function chooseImages(e:Event){selectedImages.value=Array.from((e.target as HTMLInputElement).files??[]);imageNames.value=selectedImages.value.map(f=>f.name);}
function clearFiles(){if(fileInput.value)fileInput.value.value='';if(imageInput.value)imageInput.value.value='';fileNames.value=[];imageNames.value=[];selectedFiles.value=[];selectedImages.value=[];}
function viewportChanged(){const v=window.visualViewport;keyboardInset.value=v?Math.max(0,window.innerHeight-v.height-v.offsetTop):0;}
async function refreshHistory(){if(page.value==='imports')await loadImports();}
async function removeAssignment(a:any){if(!confirm('删除这项作业？只影响当前孩子，完成记录也将移除。'))return;await act(async()=>{await api('/assignments/'+a.id,{method:'DELETE',body:JSON.stringify({revision:a.revision})});edit.value=null;await loadAssignments();notice.value='已删除';});}
const sharedEntry=isFamilyEntry(),sharedState=ref<any>({enabled:false}),sharedUrl=ref('');
let originalOverflow='';
watch(()=>Boolean(draft.value||edit.value||preview.value||composerOpen.value),open=>{if(open){originalOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}else document.body.style.overflow=originalOverflow;});
const status:Record<string,string>={queued:'等待分析',running:'正在分析',review:'待审核',failed:'分析失败',published:'已发布'};
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作失败';}finally{busy.value=false;}}
function expired(){taskRequest++;me.value=null;children.value=[];assignments.value=[];draft.value=null;imports.value=[];edit.value=null;devices.value=[];sharedUrl.value='';sharedState.value={enabled:false};currentImport.value=null;page.value='today';composerOpen.value=false;activeSubject.value='';text.value='';clearFiles();closePreview();}
let taskRequest=0;
async function loadAssignments(){const request=++taskRequest;const cid=selected.value;if(!cid){assignments.value=[];return;}let items:any[]=[];
 if(parent.value)items=await api(`/assignments?childId=${cid}&date=${date.value}&pending=${pending.value}`);
 else {for(let offset=0;;offset+=500){const batch=await api(`/assignments?childId=${cid}&view=child&offset=${offset}`);items.push(...batch);if(batch.length<500)break;}}
 if(request===taskRequest&&cid===selected.value&&me.value)assignments.value=items;
}
function rememberChild(){if(!parent.value)localStorage.setItem('homework_selected_child',selected.value);}
async function loadImports(){if(parent.value)imports.value=await api('/imports');}
async function init(){me.value=await api('/me');children.value=await api('/children');if(!children.value.some(c=>c.id===selected.value))selected.value=children.value.find(c=>c.id===localStorage.getItem('homework_selected_child'))?.id??children.value[0]?.id??'';if(!targetIds.value.length&&selected.value)targetIds.value=[selected.value];await loadAssignments();}
async function login(){await act(async()=>{const s=await api(loginMode.value==='parent'?'/auth/login':'/auth/pair',{method:'POST',body:JSON.stringify(loginMode.value==='parent'?{password:password.value}:{code:code.value})});localStorage.setItem('homework_token',s.token);password.value='';code.value='';await init();});}
async function logout(){await act(async()=>{await api('/auth/logout',{method:'POST'});localStorage.removeItem(tokenStorageKey());expired();});}
async function changePage(p:string){if(busy.value)return;document.querySelectorAll<HTMLDetailsElement>('.more-menu[open]').forEach(menu=>menu.open=false);page.value=p;await act(async()=>{await loadAssignments();if(p==='imports')await loadImports();if(p==='family'){devices.value=await api('/devices');const state=await api('/family-link');if(state.id!==sharedState.value.id)sharedUrl.value='';sharedState.value=state;}});}
async function toggle(a:any){await act(async()=>{await api(`/assignments/${a.id}/complete`,{method:'PUT',body:JSON.stringify({completed:!a.completed,revision:a.revision})});await loadAssignments();});}
async function upload(mode:'manual'|'ai'){await act(async()=>{if(mode==='manual'){if(selectedFiles.value.length||selectedImages.value.length)throw new Error('直接录入仅处理文字，请先移除附件或选择 Kimi 整理');const r=await api('/imports/manual',{method:'POST',body:JSON.stringify({text:text.value,workDate:date.value,childIds:targetIds.value})});text.value='';await refreshHistory();draft.value=await api(`/imports/${r.id}`);currentImport.value=draft.value;composerOpen.value=false;notice.value='直接录入已拆分为任务，请审核后发布；未调用AI。';return;}const f=new FormData();f.set('text',text.value);f.set('workDate',date.value);f.set('childIds',JSON.stringify(targetIds.value));const files=[...selectedFiles.value,...selectedImages.value];if(files.length>5||files.some(f=>f.size>8*1024*1024))throw new Error('最多5个文件，每个不超过8MB');for(const file of files)f.append('files',file);const r=await api('/imports',{method:'POST',body:f});text.value='';clearFiles();await refreshHistory();draft.value=await api(`/imports/${r.id}`);currentImport.value=draft.value;composerOpen.value=false;notice.value='已提交，分析结果需家长审核后发布';});}
async function openDraft(id:string){mergeSelection.value=[];await act(async()=>{draft.value=await api(`/imports/${id}`);currentImport.value=draft.value;if(!draft.value.result)draft.value.result={items:[],notices:[]};});}
async function saveDraft(){await api(`/imports/${draft.value.id}`,{method:'PUT',body:JSON.stringify({version:draft.value.version,result:draft.value.result,childIds:draft.value.child_ids,workDate:draft.value.work_date})});draft.value=await api(`/imports/${draft.value.id}`);currentImport.value=draft.value;await refreshHistory();}
async function publish(){await act(async()=>{await saveDraft();await api(`/imports/${draft.value.id}/publish`,{method:'POST',body:JSON.stringify({version:draft.value.version})});if(currentImport.value)currentImport.value={...currentImport.value,status:'published'};draft.value=null;await refreshHistory();await loadAssignments();notice.value='已发布到孩子端';});}
async function retry(id:string){await act(async()=>{await api(`/imports/${id}/retry`,{method:'POST'});draft.value=null;currentImport.value=await api(`/imports/${id}`);await refreshHistory();});}
async function withdraw(id:string){if(!confirm('撤回后，孩子端作业及该批完成记录将移除。确定撤回？'))return;await act(async()=>{await api(`/imports/${id}/withdraw`,{method:'POST'});draft.value=null;currentImport.value=await api(`/imports/${id}`);await refreshHistory();await loadAssignments();});}
async function addChild(){await act(async()=>{const c=await api('/children',{method:'POST',body:JSON.stringify({name:name.value,grade:grade.value})});name.value='';grade.value='';selected.value=c.id;targetIds.value=[c.id];await init();});}
async function createShared(reset=false){if(reset&&!confirm('重新生成后，旧共享链接立即失效。确定继续？'))return;await act(async()=>{const r=await api('/family-link',{method:'POST',body:JSON.stringify({reset})});sharedState.value={enabled:true,id:r.id};sharedUrl.value=location.origin+'/child#access='+encodeURIComponent(r.token);});}
async function revokeShared(){if(!confirm('撤销后，使用该共享链接的孩子页面将无法继续访问。确定撤销？'))return;await act(async()=>{await api('/family-link',{method:'DELETE'});sharedState.value={enabled:false};sharedUrl.value='';});}
async function copyShared(){await act(async()=>{await navigator.clipboard.writeText(sharedUrl.value);notice.value='家庭共享链接已复制，请保存完整链接。';});}
async function makePair(){await act(async()=>{const r=await api('/pairing',{method:'POST',body:JSON.stringify({childId:pairChild.value||null})});pairing.value=r.code;});}
async function revoke(id:string){await act(async()=>{await api(`/devices/${id}`,{method:'DELETE'});devices.value=await api('/devices');});}
async function showAttachment(id:string){await act(async()=>{closePreview();preview.value=await attachment(id);});}
function closePreview(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';}
async function details(a:any){await act(async()=>{const attachments=await api(`/assignments/${a.id}/attachments`);edit.value={...a,dueDate:a.due_date,priorityReason:a.priority_reason??'',warning:'',attachments};});}
async function saveAssignment(){await act(async()=>{await api(`/assignments/${edit.value.id}`,{method:'PUT',body:JSON.stringify(edit.value)});edit.value=null;await loadAssignments();notice.value='已更新，孩子需重新确认完成';});}
function blankItem(){return {subject:'语文',content:'',priority:'normal',priorityReason:'',dueDate:null,materials:'',warning:''};}
function splitDraft(index:number){const item=draft.value.result.items[index];const parts=item.content.split(/\n+/).map((s:string)=>s.trim()).filter(Boolean);if(parts.length<2){error.value='请先将独立要求分行，再点击拆分；每行生成一项任务。';return;}if(draft.value.result.items.length+parts.length-1>100){error.value='任务超过100项，请分批处理';return;}draft.value.result.items.splice(index,1,...parts.map((content:string)=>({...item,content})));mergeSelection.value=[];}
function mergeDraft(){const indexes=[...new Set(mergeSelection.value)].sort((a,b)=>a-b);const items=indexes.map(i=>draft.value.result.items[i]);if(items.length<2)return;if(items.some(i=>i.subject!==items[0].subject||i.dueDate!==items[0].dueDate)){error.value='合并前请先将所选任务的学科和截止日期调整一致。';return;}const join=(key:string)=>[...new Set(items.map(i=>i[key]).filter(Boolean))].join('；');const merged={...items[0],content:items.map(i=>i.content).join('\n'),priority:items.some(i=>i.priority==='high')?'high':'normal',priorityReason:join('priorityReason'),materials:join('materials'),warning:join('warning')};if(merged.content.length>3000||merged.priorityReason.length>200||merged.materials.length>500||merged.warning.length>500){error.value='合并后内容过长，请减少所选任务；没有删除任何内容。';return;}for(const index of [...indexes].reverse())draft.value.result.items.splice(index,1);draft.value.result.items.splice(indexes[0],0,merged);mergeSelection.value=[];}
function cost(value:number){return Number(value??0).toFixed(4);}
function usageTotals(billing:any){return billing.attempts.reduce((sum:any,a:any)=>({input:sum.input+(a.usage?.prompt_tokens??0),output:sum.output+(a.usage?.completion_tokens??0)}),{input:0,output:0});}
function printPage(){window.print();}
let timer:ReturnType<typeof setInterval>;let refreshing=false;
function sharedHashChanged(){if(sharedEntry)location.reload();}
onMounted(()=>{window.visualViewport?.addEventListener('resize',viewportChanged);window.visualViewport?.addEventListener('scroll',viewportChanged);window.addEventListener('hashchange',sharedHashChanged);window.addEventListener('session-expired',expired);if(sharedEntry){if(initializeFamilyEntry())void act(init);else error.value='请使用家长发送的完整家庭共享链接打开；不需要设备配对。';}else if(localStorage.getItem('homework_token'))void act(init);timer=setInterval(async()=>{if(!me.value||busy.value||refreshing||document.hidden)return;refreshing=true;try{if(page.value==='imports')await loadImports();if(page.value==='today'&&!draft.value&&!edit.value&&!composerOpen.value)await loadAssignments();const active=draft.value??currentImport.value;if((draft.value||page.value==='today')&&active&&['queued','running'].includes(active.status)){const latest=await api(`/imports/${active.id}`);if(!latest.result)latest.result={items:[],notices:[]};currentImport.value=latest;if(draft.value?.id===latest.id)draft.value=latest;}}catch(e){error.value=e instanceof Error?e.message:'同步失败';}finally{refreshing=false;}},5000);});
onUnmounted(()=>{document.body.style.overflow=originalOverflow;window.visualViewport?.removeEventListener('resize',viewportChanged);window.visualViewport?.removeEventListener('scroll',viewportChanged);window.removeEventListener('hashchange',sharedHashChanged);clearInterval(timer);window.removeEventListener('session-expired',expired);closePreview();});
</script>

<template>
 <div v-if="!me&&sharedEntry" class="shared-entry"><section class="panel"><h1>孩子任务</h1><p role="alert">{{busy?'正在加载任务…':error||'请从家长发送的完整家庭共享链接进入，无需设备配对。'}}</p><a href="/">返回登录入口</a></section></div>
 <div v-else-if="!me" class="login-shell">
  <section class="login-card"><div class="brand-icon">福</div><p class="eyebrow">HOMEWORK, MADE SIMPLE</p><h1>fufuyun-homework</h1><p class="muted">把零散的消息，变成清晰的一天。</p>
   <div class="tabs"><button :class="{active:loginMode==='child'}" @click="loginMode='child'">孩子设备配对</button><button :class="{active:loginMode==='parent'}" @click="loginMode='parent'">家长登录</button></div>
   <form @submit.prevent="login"><label v-if="loginMode==='parent'">家长密码<input v-model="password" type="password" autocomplete="current-password" required></label><label v-else>12 位配对码<input v-model="code" placeholder="由家长在家庭设置中生成" maxlength="12" autocomplete="off" required></label><button class="primary wide" :disabled="busy">{{busy?'正在连接…':'进入作业助手'}}</button></form>
   <p class="muted small">家长可通过网页管理，也可使用微信小程序。孩子配对后无需微信账号。</p><p v-if="error" role="alert" class="error">{{error}}</p>
  </section><aside class="login-art"><span>慢慢来，<br>一件一件完成。</span><div class="art-card">✓ 读一篇喜欢的文章<br>□ 写下今天的小收获<br>□ 留一点时间给自己</div></aside>
 </div>
 <div v-else class="app-shell" :class="{'child-mode':!parent}">
  <main :class="{'with-dock':parent&&page==='today'}"><header v-if="parent" class="compact-header no-print"><template v-if="page==='today'"><label class="sr-only" for="parent-child">孩子</label><select id="parent-child" v-model="selected" :disabled="busy" @change="selectedChild"><option v-for="c in children" :key="c.id" :value="c.id">{{c.name}}</option><option v-if="!children.length" value="">请添加孩子</option></select><label class="sr-only" for="work-date">作业日期</label><input id="work-date" v-model="date" type="date" :disabled="busy" @change="act(loadAssignments)"></template><button v-else class="quiet" @click="changePage('today')">‹ 整理作业</button><details class="more-menu"><summary>更多</summary><nav><button @click="changePage('imports')">导入记录</button><button @click="changePage('family')">家庭与设备</button><button @click="printPage">打印作业</button><button @click="logout">退出登录</button></nav></details></header>
   <p v-if="error" role="alert" class="error no-print">{{error}}</p><p v-if="notice" role="status" class="success no-print">{{notice}}</p>
   <template v-if="!parent"><header class="child-header"><label class="sr-only" for="child-name">切换孩子</label><select id="child-name" v-model="selected" :disabled="busy" @change="selectedChild"><option v-for="c in children" :key="c.id" :value="c.id">{{c.name}}的任务</option></select><details class="more-menu no-print"><summary>更多</summary><nav><button @click="printPage">打印</button><button :disabled="busy" @click="logout">退出</button></nav></details></header><div v-if="!children.length" class="empty">请家长先添加孩子。</div><ChildTasks v-else :key="selected" :tasks="assignments" :busy="busy" :name="child?.name??''" @toggle="toggle" @details="details"/></template>
   <template v-if="page==='today'&&parent">
    <div v-if="subjects.length>1" class="subject-filters no-print" role="group" aria-label="筛选学科"><button :aria-pressed="activeSubject===''" :class="{active:activeSubject===''}" @click="activeSubject=''">全部 {{assignments.length}}</button><button v-for="s in subjects" :key="s.subject" :aria-pressed="activeSubject===s.subject" :class="{active:activeSubject===s.subject}" @click="activeSubject=s.subject">{{s.subject}} {{s.total}}</button></div>
    <div v-if="currentImport" class="current-import no-print"><span>{{status[currentImport.status]}}</span><button class="quiet" :disabled="busy" @click="openDraft(currentImport.id)">查看结果</button></div>
    <div class="list-heading"><h2>已有作业 <small>{{assignments.length}} 项</small></h2><label class="check no-print"><input v-model="pending" type="checkbox" @change="act(loadAssignments)">所有未完成</label></div>
    <section v-if="!children.length" class="empty">请在“更多 → 家庭与设备”添加孩子。</section>
    <div v-for="(items,subject) in groups" :key="subject" class="subject-group"><h3>{{subject}}</h3><article v-for="a in items" :key="a.id" class="assignment" :class="{completed:a.completed}"><div class="assignment-body"><span v-if="a.updated" class="update-label">内容有更新</span><span v-if="a.priority==='high'" class="priority-label">优先任务</span><p class="assignment-text">{{a.content}}</p><p v-if="a.materials" class="muted">准备：{{a.materials}}</p><div class="meta"><span v-if="pending">所属 {{a.work_date}}</span><span v-if="a.due_date">截止 {{a.due_date}}</span><span>{{a.completed?'已完成':'待完成'}}</span></div></div><div class="card-actions no-print"><button class="quiet" :disabled="busy" @click="toggle(a)">{{a.completed?'取消完成':'标记完成'}}</button><button class="quiet" :disabled="busy" @click="details(a)">详情 / 编辑</button><button class="quiet danger" :disabled="busy" @click="removeAssignment(a)">删除</button></div></article></div>
    <div v-if="children.length&&!assignments.length" class="empty">暂无作业，点击底部“新增任务”。</div>
    <div v-if="!draft&&!edit&&!preview&&!composerOpen" class="bottom-dock no-print"><button class="primary wide" :disabled="busy||!children.length" @click="composerOpen=true">新增任务</button></div>
   </template>
   <template v-if="page==='imports'&&parent">
    <section class="panel"><h2>导入记录</h2><div v-if="!imports.length" class="empty">还没有导入记录</div><div v-for="j in imports" :key="j.id" class="import-row"><div><strong>{{j.work_date}}</strong><p class="muted source-snippet">{{j.source_text||'图片消息'}}</p><p v-if="j.error" class="error">{{j.error}}</p></div><span class="badge">{{status[j.status]}}</span><button class="outline" @click="openDraft(j.id)">查看{{j.status==='review'?' / 审核':''}}</button></div></section>
   </template>
   <template v-if="page==='family'&&parent"><h2>家庭与设备</h2><section class="panel"><h2>孩子档案</h2><div class="child-list"><div v-for="c in children" :key="c.id" class="child-card"><span class="avatar">{{c.name.slice(0,1)}}</span><div><strong>{{c.name}}</strong><p class="muted">{{c.grade||'未设置年级 / 班级'}}</p></div></div></div><form class="toolbar" @submit.prevent="addChild"><label>孩子昵称<input v-model="name" required maxlength="40"></label><label>年级 / 班级<input v-model="grade" maxlength="40"></label><button class="primary" :disabled="busy">添加孩子</button></form></section><section class="panel"><h2>家庭共享链接 · 孩子免配对入口</h2><p class="muted">所有孩子设备打开同一个专属链接，直接切换名字查看和勾选任务。持有链接的人可访问本家庭已发布作业，请只分享给家人。</p><button v-if="!sharedState.enabled" class="primary" :disabled="busy||!children.length" @click="createShared()">生成家庭共享链接</button><template v-else><p class="badge">共享链接已启用</p><p v-if="!sharedUrl" class="muted">完整链接仅在生成后显示，请使用此前保存的链接；未保存可重新生成。</p><label v-if="sharedUrl">请保存完整链接<textarea :value="sharedUrl" readonly rows="3" @focus="($event.target as HTMLTextAreaElement).select()"></textarea></label><button v-if="sharedUrl" class="primary" @click="copyShared">复制共享链接</button><button class="outline" :disabled="busy" @click="createShared(true)">重新生成（旧链接失效）</button><button class="quiet" :disabled="busy" @click="revokeShared">撤销共享链接</button></template></section><section class="panel"><h2>设备配对（原有功能）</h2><p class="muted">在孩子设备打开同一个网址，输入一次性配对码即可。</p><div class="toolbar"><label>设备用途<select v-model="pairChild"><option value="">共用设备：可切换全部孩子</option><option v-for="c in children" :value="c.id" :key="c.id">{{c.name}}的专用设备</option></select></label><button class="primary" :disabled="busy||!children.length" @click="makePair">生成配对码</button></div><p v-if="pairing" class="pair-code">{{pairing}}<small>10 分钟有效，仅可使用一次</small></p><h3>已配对设备</h3><div v-for="d in devices" :key="d.id" class="import-row"><span>{{d.child_id?children.find(c=>c.id===d.child_id)?.name+'的设备':'共用设备'}} · {{d.created_at}}</span><button class="outline" @click="revoke(d.id)">撤销访问</button></div><p v-if="!devices.length" class="muted">暂无设备，配对完成后重新进入本页刷新。</p></section></template>

  </main>
 </div>
 <div v-if="composerOpen&&parent" class="modal-backdrop no-print"><section class="modal entry-modal" role="dialog" aria-modal="true" aria-label="新增任务"><header><h2>新增任务</h2><button class="quiet" :disabled="busy" @click="composerOpen=false">关闭</button></header><p v-if="error" class="error" role="alert">{{error}}</p><label>作业日期<input v-model="date" type="date"></label><details v-if="children.length>1" class="target-children"><summary>分配给 {{targetIds.map(id=>children.find(c=>c.id===id)?.name).join('、')||'请选择孩子'}}</summary><label v-for="c in children" :key="c.id" class="check"><input v-model="targetIds" type="checkbox" :value="c.id">{{c.name}}</label></details><label for="source-text">作业内容</label><textarea id="source-text" v-model="text" rows="6" maxlength="50000" placeholder="粘贴作业，每行或每个编号一项；可带语文作业等学科标题"></textarea><div class="file-actions"><button class="outline" :disabled="busy" @click="fileInput?.click()">上传文件</button><button class="outline" :disabled="busy" @click="imageInput?.click()">添加截图</button></div><input ref="fileInput" class="sr-only" type="file" multiple accept=".txt,.json" @change="chooseFiles"><input ref="imageInput" class="sr-only" type="file" multiple accept="image/jpeg,image/png,image/webp" @change="chooseImages"><div v-if="fileNames.length||imageNames.length" class="file-list"><span v-for="(f,i) in [...fileNames,...imageNames]" :key="i">{{f}}</span><button class="quiet" :disabled="busy" @click="clearFiles">移除附件</button></div><p class="muted small">直接录入保留任务原文。附件由 Kimi 处理，最多5个、每个8MB。</p><p v-if="!me.aiConfigured" class="muted small">Kimi 未配置，可直接录入。</p><div class="modal-actions entry-actions" :style="{bottom:keyboardInset?keyboardInset+'px':undefined}"><button class="outline" :disabled="busy||!targetIds.length||!text.trim()||!!(fileNames.length+imageNames.length)" @click="upload('manual')">直接录入</button><button class="primary" :disabled="busy||!me.aiConfigured||!targetIds.length||(!text.trim()&&!fileNames.length&&!imageNames.length)" @click="upload('ai')">交给 Kimi 整理</button></div></section></div>
 <div v-if="draft" class="modal-backdrop no-print"><section class="modal" role="dialog" aria-modal="true" aria-label="审核作业"><header><h2>审核作业 · {{status[draft.status]}}</h2><button class="quiet" @click="draft=null">关闭</button></header><p v-if="error" class="error" role="alert">{{error}}</p><section v-if="draft.import_kind==='manual'" class="success">直接录入 · 请核对后发布</section><details v-else-if="draft.billing" class="billing-card"><summary>Kimi 用量与费用</summary><p v-if="draft.billing.legacyUsageUnknown" class="error">旧版历史用量未知，不能按免费计算；该批仅支持手动整理。</p><strong>本版本已记录的 AI 费用（估算 / 预留）：¥{{cost(draft.billing.committedCny)}} / ¥{{draft.billing.budgetCny.toFixed(2)}}</strong><p>生成 {{draft.billing.attempts.length}} / 2 次 · 已知输入 {{usageTotals(draft.billing).input}} / 输出 {{usageTotals(draft.billing).output}} tokens（含思考）</p><p class="muted small">用量未知时保留预留费用；金额不等于平台账单。编辑、发布和分配多个孩子不再调用 AI。</p><p v-if="draft.billing.attempts.some((a:any)=>a.state==='unknown')" class="error">有请求用量未知，已保留其预留费用。</p></details><details><summary>原始消息与附件</summary><pre>{{draft.source_text||'无文字'}}</pre><button v-for="f in draft.attachments" :key="f.id" class="outline" @click="showAttachment(f.id)">{{f.name}}</button></details><p v-if="draft.error" class="error">{{draft.error}}</p><template v-if="['review','failed'].includes(draft.status)"><label>所属日期<input v-model="draft.work_date" type="date"></label><fieldset><legend>分配孩子</legend><label v-for="c in children" :key="c.id" class="check"><input v-model="draft.child_ids" type="checkbox" :value="c.id">{{c.name}}</label></fieldset><p v-if="draft.result?.notices?.length" class="success">通知（不会作为作业发布）：{{draft.result.notices.join('；')}}</p><p class="muted">请与原消息核对日期、页码、题号和孩子；相似作业不会自动覆盖已有内容。</p><button class="outline" :disabled="mergeSelection.length<2" @click="mergeDraft">合并所选任务（{{mergeSelection.length}}）</button><article v-for="(i,index) in draft.result?.items" :key="index" class="draft-item"><label class="check"><input v-model="mergeSelection" type="checkbox" :value="index">选择合并</label><label>科目<input v-model="i.subject" maxlength="30"></label><label>优先级<select v-model="i.priority"><option value="high">优先任务</option><option value="normal">其他任务</option></select></label><label>分类依据（仅家长可见）<input v-model="i.priorityReason" maxlength="200"></label><label>作业要求<textarea v-model="i.content" rows="3" maxlength="3000"></textarea></label><div class="toolbar"><label>截止日期<input :value="i.dueDate??''" type="date" @input="i.dueDate=($event.target as HTMLInputElement).value||null"></label><label>准备材料<input v-model="i.materials" maxlength="500"></label></div><p v-if="i.warning" class="error">待确认：{{i.warning}}</p><button class="quiet" @click="splitDraft(Number(index))">按换行拆分任务</button><button class="quiet" @click="draft.result.items.splice(index,1);mergeSelection=[]">删除这一项</button></article><button class="outline" @click="draft.result.items.push(blankItem())">添加作业</button><div class="modal-actions"><button v-if="draft.status==='failed'" class="outline" :disabled="busy" @click="retry(draft.id)">重新分析</button><button class="outline" :disabled="busy" @click="act(async()=>{await saveDraft();notice='草稿已保存'})">保存草稿</button><button class="primary" :disabled="busy||!draft.result?.items?.length" @click="publish">发布作业</button></div></template><template v-else-if="draft.status==='published'"><p>已发布给孩子。修改个别作业请到“整理作业”；整批重新审核可先撤回。</p><button class="outline" @click="withdraw(draft.id)">撤回整批作业</button></template><p v-else>正在排队或分析，请稍候，结果会自动更新。</p></section></div>
 <div v-if="edit" class="modal-backdrop no-print"><section class="modal" role="dialog" aria-modal="true" aria-label="作业详情"><header><h2>{{edit.subject}} · 作业详情</h2><button class="quiet" @click="edit=null">关闭</button></header><p v-if="error" class="error">{{error}}</p><template v-if="parent"><label>科目<input v-model="edit.subject"></label><label>要求<textarea v-model="edit.content" rows="6"></textarea></label><label>截止日期<input :value="edit.dueDate??''" type="date" @input="edit.dueDate=($event.target as HTMLInputElement).value||null"></label><label>材料<input v-model="edit.materials"></label><label>优先级<select v-model="edit.priority"><option value="high">优先任务</option><option value="normal">其他任务</option></select></label><label>分类依据（仅家长可见）<input v-model="edit.priorityReason" maxlength="200"></label><p class="muted">更新后将取消原完成状态，提醒孩子重新确认。只修改当前孩子的这一项。</p><button class="primary" :disabled="busy" @click="saveAssignment">保存修改</button></template><template v-else><p class="assignment-text">{{edit.content}}</p><p v-if="edit.materials">准备：{{edit.materials}}</p><p>截止：{{edit.due_date||'未指定'}}</p></template><h3>原始附件</h3><button v-for="f in edit.attachments" :key="f.id" class="outline" @click="showAttachment(f.id)">{{f.name}}</button><p v-if="!edit.attachments.length" class="muted">无附件</p></section></div>
 <div v-if="preview" class="modal-backdrop preview no-print"><button class="primary" @click="closePreview">关闭附件</button><iframe :src="preview" title="原始附件预览"></iframe></div>
</template>
